    text(`Wave ${state.wave} / ${WIN_WAVES}`, FIELD.width / 2, 30, 30, PALETTE.text, 'center', '700');
    text(`Best ${best}`, FIELD.width - 28, 30, 30, PALETTE.text, 'right', '700');
    // Lives as glowing buds.
