    roundRect(x, y, PANEL.width, height, 20);
    context.fill();
    context.strokeStyle = PALETTE.panelLine;
    context.lineWidth = 2;
    roundRect(x, y, PANEL.width, height, 20);
    context.stroke();
    text(title, FIELD.width / 2, y + 92, 56, PALETTE.text, 'center', '800');
    for (let i = 0; i < lines.length; i += 1) {
